const profile = mkdtempSync(join(tmpdir(), 'disc-dbg-'));
const chrome = spawn('google-chrome', ['--headless=new','--no-sandbox','--disable-gpu',`--remote-debugging-port=${PORT}`,`--user-data-dir=${profile}`,'--window-size=1440,1000','about:blank'],{stdio:['ignore','pipe','pipe']});
class CDP {
  static async connect(){ for(let i=0;i<50;i++){ try{ const t=await (await fetch(`http://127.0.0.1:${PORT}/json/list`)).json(); const p=t.find(x=>x.type==='page'); if(p) return new CDP(p.webSocketDebuggerUrl);}catch(_){} await sleep(200);} throw new Error('no chrome'); }
  constructor(u){this.url=u;this.id=0;this.p=new Map()}
  async open(){ this.ws=new WebSocket(this.url); await new Promise((r,j)=>{this.ws.onopen=r;this.ws.onerror=j}); this.ws.onmessage=(ev)=>{const m=JSON.parse(ev.data); if(m.id&&this.p.has(m.id)){const {res,rej}=this.p.get(m.id);this.p.delete(m.id); m.error?rej(new Error(JSON.stringify(m.error))):res(m.result);}}; }
  send(method,params={}){const id=++this.id;this.ws.send(JSON.stringify({id,method,params}));return new Promise((res,rej)=>this.p.set(id,{res,rej}))}
}
const ev=async(c,e)=>{const r=await c.send('Runtime.evaluate',{expression:e,returnByValue:true,awaitPromise:true}); if(r.exceptionDetails) throw new Error(JSON.stringify(r.exceptionDetails)); return r.result.value;};
try{
  const c=await CDP.connect(); await c.open();
  await c.send('Runtime.enable'); await c.send('Page.enable');
  await c.send('Emulation.setDeviceMetricsOverride',{width:1440,height:1000,deviceScaleFactor:1,mobile:false});
  await c.send('Page.navigate',{url:'file://'+file}); await sleep(700);
  await ev(c,`document.querySelector('.js-open-disc').click()`); await sleep(300);
  // перехват setPointerCapture
  await ev(c,`window.__cap=[]; const orig=Element.prototype.setPointerCapture; Element.prototype.setPointerCapture=function(pid){ try{ orig.call(this,pid); window.__cap.push('ok pid='+pid+' el='+(this.textContent||'').slice(0,12)); }catch(err){ window.__cap.push('ERR pid='+pid+' '+err.name+': '+err.message); } }; 'hooked'`);
  const r1=await ev(c,`(()=>{const li=document.querySelector('#draggable-list1 li:nth-child(2)');const r=li.getBoundingClientRect();return{x:r.left+r.width/2,y:r.top+r.height/2}})()`);
  await c.send('Input.dispatchMouseEvent',{type:'mouseMoved',x:r1.x,y:r1.y});
  await c.send('Input.dispatchMouseEvent',{type:'mousePressed',x:r1.x,y:r1.y,button:'left',clickCount:1});
  await sleep(100);
  await c.send('Input.dispatchMouseEvent',{type:'mouseReleased',x:r1.x,y:r1.y-100,button:'left',clickCount:1});
  await sleep(150);
  console.log(await ev(c,`({cap:window.__cap})`));
}catch(e){console.error(e)}finally{chrome.kill('SIGKILL')}
