const onDragStart = (li, e) => {
  drag.li = li;
  drag.ul = li.closest(".disc-list");
  drag.pid = e.pointerId;
  drag.lastY = e.clientY;

  const rect = li.getBoundingClientRect();
  drag.offY = e.clientY - rect.top;

  // призрак, следующий за курсором
  const ghostLi = li.cloneNode(true);
  const ghost = document.createElement("ul");
  ghost.className = "disc-list disc-ghost";
  ghost.style.left = rect.left + "px";
  ghost.style.width = rect.width + "px";
  ghost.appendChild(ghostLi);
  document.body.appendChild(ghost);
  drag.ghost = ghost;

  li.classList.add("is-dragging");
  document.body.classList.add("is-reordering");
  // слушатели на document: не зависим от ретаргетинга pointer-событий
  document.addEventListener("pointermove", onDragMove);
  document.addEventListener("pointerup", onDragEnd);
  document.addEventListener("pointercancel", onDragEnd);
  try { li.setPointerCapture(e.pointerId); } catch (_) {}

  const loop = () => {
    if (!drag.li) return;
    const r = bodyEl.getBoundingClientRect();
    if (drag.lastY < r.top + 60) bodyEl.scrollTop -= 12;
    else if (drag.lastY > r.bottom - 60) bodyEl.scrollTop += 12;
    drag.raf = requestAnimationFrame(loop);
  };
  drag.raf = requestAnimationFrame(loop);
  moveGhost(e.clientY);
};

