const onDragEnd = (e) => {
  if (!drag.li || (e && e.pointerId !== undefined && e.pointerId !== drag.pid)) return;
  cancelAnimationFrame(drag.raf);
  if (drag.ghost) { drag.ghost.remove(); drag.ghost = null; }
  drag.li.classList.remove("is-dragging");
  qsa(".disc-item.is-over", drag.ul).forEach((x) => x.classList.remove("is-over"));
  document.body.classList.remove("is-reordering");
  document.removeEventListener("pointermove", onDragMove);
  document.removeEventListener("pointerup", onDragEnd);
  document.removeEventListener("pointercancel", onDragEnd);
  try { drag.li.releasePointerCapture(drag.pid); } catch (_) {}
  drag.li = null; drag.ul = null; drag.pid = -1;
};

